package main

import "fmt"

func main() {
	// for 的三种形式
	for i := 0; i < 3; i++ {
		fmt.Println("三段式:", i)
	}
	j := 0
	for j < 2 {
		fmt.Println("只有条件:", j)
		j++
	}

	// range 遍历切片、map、字符串、整数
	nums := []int{10, 20}
	for i, v := range nums {
		fmt.Println("切片:", i, v)
	}
	scores := map[string]int{"语文": 90, "数学": 80}
	for k, v := range scores {
		fmt.Println("成绩:", k, v)
	}
	for _, r := range "Go" {
		fmt.Printf("字符: %c\n", r)
	}
	for i := range 2 {
		fmt.Println("序号:", i)
	}

	// break 和 continue
	for i := 0; i < 4; i++ {
		if i == 1 {
			continue
		}
		if i == 3 {
			break
		}
		fmt.Println("结果:", i)
	}

	// 带标签的 break
outer:
	for i := 0; i < 2; i++ {
		for k := 0; k < 2; k++ {
			if i+k == 1 {
				break outer
			}
			fmt.Println("嵌套:", i, k)
		}
	}
}
